1	import AppKit
2	
3	#if FRAMEJOB_DEV_TOOLS
4	/// `perform_menu_item`'s main-thread half (road map 11's V2b): the main
5	/// menu's leaves, a path looked up in it, whether an item may be run at all,
6	/// which object answers it in a NAMED window's responder chain, whether that
7	/// object enables it, and the run itself.
8	///
9	/// Every member is main-thread only; the handler
10	/// (`AgentServer+MenuItem.swift`) reaches each through `onMain`.
11	///
12	/// **Delivery is never nil-targeted.** A nil-target `sendAction` or
13	/// `performActionForItem` walks the KEY window's chain, and an agent-driven
14	/// app is usually inactive with no key window, so the editor's actions would
15	/// fall through to the app delegate and do nothing (V1's S0). `responders`
16	/// walks the named window's own chain instead, the way AppKit would if that
17	/// window were key, then the app's tail; `target` is the first object in it
18	/// that answers the selector, and `perform` sends the action to THAT object.
19	///
20	/// **Refusal is an allow-table.** Only a selector `UIMenuTable.swift` reads
21	/// `none`, `sheet` or `window` may run: `framework` (AppKit's own quit, open,
22	/// save, close, undo …) and `modal` (a modal loop inside the call, which
23	/// holds the agent server's one request open) are refused by name, and so is
24	/// every selector with no row — AppKit's injected items and anything added
25	/// to the menu since the inventory was read.
26	///
27	/// **Undo.** An action run here is outside an AppKit event, so an edit it
28	/// makes would land in the implicit event group AppKit never closes and merge
29	/// with the next (app/CLAUDE.md "Undo and dirty tracking"). On a
30	/// `ProjectDocument`, `perform` runs the action inside
31	/// `inUndoGroupIfRegistered`: the explicit group opens at the item's first
32	/// undo registration, so an item's edits are one step (M3), and an item that
33	/// registers nothing — Zoom In — leaves undo and redo as they were (#167,
34	/// `v2_menu.py` U2). An `NSText` target on the document's own manager has
35	/// typing undo that bypasses `registerUndo`, so there, and for a target on
36	/// the document's manager on any other document, `perform` keeps the eager
37	/// group, `ProjectDocument.performGroupedEdit`'s discipline: event
38	/// grouping off, begin, act, close exactly what it opened, restore — never a
39	/// flush. The exception is `textReadOnlySelectors`, which change no text and
40	/// so register nothing: those run in `inUndoGroupIfRegistered` too (#176,
41	/// `v2_menu.py` U3). A target whose own `undoManager` is not the document's
42	/// — the Assistant composer, and every field editor, which answers its own
43	/// `NSCellUndoManager` — gets no eager group, since its text undo lands on
44	/// its own manager and the group could only be empty (#184,
45	/// `menu_undo_probe.py` M1, M2 and V1); on a `ProjectDocument` it runs in
46	/// `inUndoGroupIfRegistered`, so a document edit it commits during the
47	/// action (a `controlTextDidChange` commit) is still one step (F1).
48	enum UIMenu {
49	    /// V1's verdicts. `none` is spelled `.plain` so no `Optional.none`
50	    /// comparison is ever ambiguous.
51	    enum Verdict: String, CaseIterable { case plain = "none", sheet, window, modal, framework }
52	    enum Refusal: String { case noAction = "no_action", framework, modal, unclassified }
53	
54	    /// The selectors an NSText target answers without changing its text, so
55	    /// without an undo registration (#176).
56	    static let textReadOnlySelectors: Set<String> = ["copy:", "selectAll:"]
57	
58	    /// A menu item that is not a submenu, and the titles leading to it.
59	    struct Leaf {
60	        let item: NSMenuItem
61	        let path: [String]
62	    }
63	
64	    enum Lookup {
65	        case item(NSMenuItem)
66	        /// `at` is the path up to and including the title not found; `titles`
67	        /// the visible titles of the level it was looked for in.
68	        case missing(at: [String], titles: [String])
69	        case submenu(titles: [String])
70	    }
71	
72	    static func selector(of item: NSMenuItem) -> String? {
73	        item.action.map { NSStringFromSelector($0) }
74	    }
75	
76	    /// Pre-order; separators skipped, hidden items kept. A submenu item is
77	    /// never a leaf itself.
78	    static func leaves(of menu: NSMenu, under path: [String] = []) -> [Leaf] {
79	        var found: [Leaf] = []
80	        for item in menu.items where !item.isSeparatorItem {
81	            let here = path + [item.title]
82	            if let submenu = item.submenu {
83	                found += leaves(of: submenu, under: here)
84	            } else {
85	                found.append(Leaf(item: item, path: here))
86	            }
87	        }
88	        return found
89	    }
90	
91	    /// The item at `path` in the main menu. Each level is validated before
92	    /// its titles are read, since a validator may retitle an item (New
93	    /// Recording… reads Stop Recording while one runs); a hidden item never
94	    /// matches.
95	    static func lookup(_ path: [String], window: NSWindow?) -> Lookup {
96	        guard var menu = NSApp.mainMenu else { return .missing(at: path, titles: []) }
97	        for (index, title) in path.enumerated() {
98	            validate(menu, window: window)
99	            let visible = menu.items.filter { !$0.isSeparatorItem && !$0.isHidden }
100	            guard let item = visible.first(where: { $0.title == title }) else {
101	                return .missing(at: Array(path.prefix(index + 1)), titles: visible.map(\.title))
102	            }
103	            let last = index == path.count - 1
104	            if let submenu = item.submenu {
105	                if last {
106	                    validate(submenu, window: window)
107	                    return .submenu(
108	                        titles: submenu.items.filter { !$0.isSeparatorItem && !$0.isHidden }
109	                            .map(\.title))
110	                }
111	                menu = submenu
112	                continue
113	            }
114	            if last { return .item(item) }
115	            return .missing(at: Array(path.prefix(index + 2)), titles: [])
116	        }
117	        return .missing(at: [], titles: [])
118	    }
119	
120	    /// Fills each level a delegate fills when it opens — Clip ▸ Look ▸'s LUT
121	    /// rows (`LookMenuFiller`) — for the named window, as AppKit would for
122	    /// the main one before it shows it.
123	    static func fillDynamic(_ menu: NSMenu, window: NSWindow?) {
124	        (menu.delegate as? LookMenuFiller)?.fill(menu, for: window)
125	        for item in menu.items {
126	            if let submenu = item.submenu { fillDynamic(submenu, window: window) }
127	        }
128	    }
129	
130	    /// Fills, then runs every validator of one level, as AppKit does before
131	    /// it shows it.
132	    private static func validate(_ menu: NSMenu, window: NSWindow?) {
133	        fillDynamic(menu, window: window)
134	        for item in menu.items where item.action != nil {
135	            _ = isEnabled(item, target: target(for: item, window: window))
136	        }
137	    }
138	
139	    /// nil when the item may run; else why not.
140	    static func refusal(for item: NSMenuItem) -> Refusal? {
141	        guard let name = selector(of: item) else { return .noAction }
142	        guard let verdict = verdicts[name] else { return .unclassified }
143	        switch verdict {
144	        case .framework: return .framework
145	        case .modal: return .modal
146	        case .plain, .sheet, .window: return nil
147	        }
148	    }
149	
150	    /// The window's responder chain from its first responder — or its
151	    /// content view, when the window itself holds first responder — then the
152	    /// window, its delegate, its controller and document; then the app, its
153	    /// delegate and the document controller. Each object once.
154	    static func responders(for window: NSWindow?) -> [AnyObject] {
155	        var chain: [AnyObject] = []
156	        var seen = Set<ObjectIdentifier>()
157	        func add(_ object: AnyObject?) {
158	            guard let object, seen.insert(ObjectIdentifier(object)).inserted else { return }
159	            chain.append(object)
160	        }
161	        if let window {
162	            var responder: NSResponder? = window.firstResponder
163	            if responder == nil || responder === window { responder = window.contentView }
164	            while let next = responder, !seen.contains(ObjectIdentifier(next)) {
165	                add(next)
166	                responder = next.nextResponder
167	            }
168	            add(window)
169	            add(window.delegate)
170	            add(window.windowController)
171	            add(window.windowController?.document)
172	        }
173	        add(NSApp)
174	        add(NSApp.delegate)
175	        add(NSDocumentController.shared)
176	        return chain
177	    }
178	
179	    /// The item's own target when it answers the action — nil when it does
180	    /// not, with no fallback to the chain, since AppKit greys such an item —
181	    /// else the first object in the chain that answers it.
182	    static func target(for item: NSMenuItem, window: NSWindow?) -> AnyObject? {
183	        guard let action = item.action else { return nil }
184	        if let own = item.target {
185	            return (own as? NSObjectProtocol)?.responds(to: action) == true ? own : nil
186	        }
187	        return responders(for: window).first {
188	            ($0 as? NSObjectProtocol)?.responds(to: action) == true
189	        }
190	    }
191	
192	    /// AppKit's rule: a menu that does not auto-enable keeps the item's own
193	    /// flag; else the target's `validateMenuItem(_:)`, else its
194	    /// `validateUserInterfaceItem(_:)`, else enabled. Never writes `isEnabled`.
195	    static func isEnabled(_ item: NSMenuItem, target: AnyObject?) -> Bool {
196	        if let menu = item.menu, !menu.autoenablesItems { return item.isEnabled }
197	        guard let target else { return false }
198	        if let validator = target as? NSMenuItemValidation {
199	            return validator.validateMenuItem(item)
200	        }
201	        if let validator = target as? NSUserInterfaceValidations {
202	            return validator.validateUserInterfaceItem(item)
203	        }
204	        return true
205	    }
206	
207	    /// Every leaf of the main menu, validated for `window`, with its verdict
208	    /// and refusal.
209	    static func listing(window: NSWindow?) -> [[String: Any]] {
210	        guard let main = NSApp.mainMenu else { return [] }
211	        fillDynamic(main, window: window)
212	        var enabled: [ObjectIdentifier: Bool] = [:]
213	        for leaf in leaves(of: main) where leaf.item.action != nil {
214	            let item = leaf.item
215	            enabled[ObjectIdentifier(item)] = isEnabled(
216	                item, target: target(for: item, window: window))
217	        }
218	        // Walked again: validation can retitle a leaf.
219	        return leaves(of: main).map { leaf in
220	            let item = leaf.item
221	            let name = selector(of: item)
222	            let state: String
223	            switch item.state {
224	            case .on: state = "on"
225	            case .mixed: state = "mixed"
226	            default: state = "off"
227	            }
228	            return [
229	                "path": leaf.path,
230	                "selector": UISnapshot.orNull(name),
231	                "verdict": UISnapshot.orNull(name.flatMap { verdicts[$0]?.rawValue }),
232	                "refusal": UISnapshot.orNull(refusal(for: item)?.rawValue),
233	                "enabled": enabled[ObjectIdentifier(item)].map { $0 as Any } ?? NSNull(),
234	                "state": state,
235	                "hidden": item.isHidden,
236	            ]
237	        }
238	    }
239	
240	    /// Sends the item's action to `target`, its undo in one explicit group on
241	    /// the window's document's manager (the header's **Undo.**); an `NSText`
242	    /// target's group is eager unless the selector is one of
243	    /// `textReadOnlySelectors`. A target with an undo manager of its own gets
244	    /// no eager group, only `inUndoGroupIfRegistered` on a `ProjectDocument`.
245	    /// False when nothing handled it.
246	    static func perform(_ item: NSMenuItem, target: AnyObject, window: NSWindow?) -> Bool {
247	        guard let action = item.action else { return false }
248	        let document = window?.windowController?.document as? NSDocument
249	        guard let manager = document?.undoManager else {
250	            return NSApp.sendAction(action, to: target, from: item)
251	        }
252	        if let own = (target as? NSResponder)?.undoManager, own !== manager {
253	            // Its text undo is its own; a document edit it commits is one step.
254	            guard let document = document as? ProjectDocument else {
255	                return NSApp.sendAction(action, to: target, from: item)
256	            }
257	            return document.inUndoGroupIfRegistered { NSApp.sendAction(action, to: target, from: item) }
258	        }
259	        if let document = document as? ProjectDocument,
260	            !(target is NSText) || textReadOnlySelectors.contains(NSStringFromSelector(action))
261	        {
262	            return document.inUndoGroupIfRegistered {
263	                NSApp.sendAction(action, to: target, from: item)
264	            }
265	        }
266	        let groupsByEvent = manager.groupsByEvent
267	        if groupsByEvent { manager.groupsByEvent = false }
268	        let level = manager.groupingLevel
269	        manager.beginUndoGrouping()
270	        let sent = NSApp.sendAction(action, to: target, from: item)
271	        // Close exactly what this call opened — never a group it did not.
272	        while manager.groupingLevel > level { manager.endUndoGrouping() }
273	        if groupsByEvent { manager.groupsByEvent = true }
274	        return sent
275	    }
